    {
      "id": "fetchPOData",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Fetch PO Data"
      },
      "inputs": {
        "script": "return {\n  poNumber: \"PO-2024-00123\",\n  vendorName: \"Acme Supplies Ltd.\",\n  totalAmount: 47500.00\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=result.Error",
          "var": "error"
        }
      }
    },
    {
      "id": "poReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "Procurement Officer Review"
      },
      "inputs": {
        "schema": {
          "schemaId": "b2f4a1e0-7c3d-4f8e-a912-5d6b8c0e1f2a",
          "fields": [
            {
              "id": "poNumber",
              "label": "PO Number",
              "type": "text",
              "direction": "input",
              "binding": "vars.fetchPOData.output.poNumber"
            },
            {
              "id": "vendorName",
              "label": "Vendor Name",
              "type": "text",
              "direction": "input",
              "binding": "vars.fetchPOData.output.vendorName"
            },
            {
              "id": "totalAmount",
              "label": "Total Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.fetchPOData.output.totalAmount"
            },
            {
              "id": "decision",
              "label": "Decision",
              "type": "select",
              "direction": "output",
              "variable": "vars.officerDecision",
              "options": ["Approve", "Reject"]
            },
            {
              "id": "notes",
              "label": "Notes (optional)",
              "type": "text",
              "direction": "output",
              "variable": "vars.officerNotes"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "Continue"
            }
          ]
        },
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": {
            "type": "group"
          }
        },
        "priority": "High",
        "title": "Purchase Order Review"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "decision": { "type": "string" },
            "notes": { "type": "string" },
            "Action": {
              "type": "string",
              "enum": ["Approve", "Reject"],
              "default": "Approve"
            }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "routeDecision",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Decision: Approve or Reject?"
      },
      "inputs": {
        "expression": "$vars.poReview.output.decision === \"Approve\"",
        "trueLabel": "Approve",
        "falseLabel": "Reject"
      }
    },
    {
      "id": "logApproved",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log PO Approved"
      },
      "inputs": {
        "script": "return {\n  message: \"PO approved\",\n  poNumber: $vars.fetchPOData.output.poNumber,\n  approvedBy: $vars.poReview.output.decision,\n  notes: $vars.poReview.output.notes\n};"
      },
      "outputs": {
        "output": {
